import{_ as e,a as o,b as r}from"./chunks/okta-authorization-server-rule.CrqafiSe.js";import{_ as n,c as a,o as i,ax as s}from"./chunks/framework.DHqKNX4U.js";const f=JSON.parse('{"title":"Microsoft 365 via Okta","description":"","frontmatter":{},"headers":[],"relativePath":"enterprise/sso/examples/microsoft-365-okta.md","filePath":"enterprise/sso/examples/microsoft-365-okta.md"}'),d={name:"enterprise/sso/examples/microsoft-365-okta.md"};function c(h,t,p,l,g,u){return i(),a("div",null,t[0]||(t[0]=[s('<h1 id="microsoft-365-via-okta" tabindex="-1">Microsoft 365 via Okta <a class="header-anchor" href="#microsoft-365-via-okta" aria-label="Permalink to &quot;Microsoft 365 via Okta&quot;">​</a></h1><p>Use this arrangement when Okta is your organisation&#39;s identity provider and Microsoft 365 sits behind it. People continue to sign in with their Microsoft work or school account, but Okta is the provider Open Archiver connects to.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>browser ──► Open Archiver ──OIDC/SAML──► Okta ──► Microsoft 365 (Entra ID)</span></span></code></pre></div><p>Compared with connecting to Entra ID directly, this route consolidates every provider your organisation uses behind one connection, and it identifies groups by readable name rather than by directory object ID.</p><div class="warning custom-block"><p class="custom-block-title">Okta identifies people by their Okta profile, not by their Microsoft account</p><p>Whichever provider sits behind Okta, the address Open Archiver receives is the one on the <strong>Okta user profile</strong>. If your Okta users have profile addresses at <code>example.com</code>, that is the domain to enter under <strong>Allowed email domains</strong> — not your Microsoft 365 tenant domain, if the two differ. A tenant name ending in <code>onmicrosoft.com</code> is very unlikely to be the correct value here.</p><p>This is the most common cause of a refused sign-in on a brokered connection, and it also means a single Okta connection covers every provider behind Okta. Configuring one Open Archiver connection per upstream provider is unnecessary and will not behave as expected, because all of them resolve to the same Okta user.</p></div><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Detail</th></tr></thead><tbody><tr><td>License</td><td>Open Archiver Enterprise with the <strong>SSO</strong> feature enabled</td></tr><tr><td>Open Archiver role</td><td>Super Admin — single sign-on is configured under <strong>Admin → Single Sign-On</strong></td></tr><tr><td>Okta rights</td><td>Administrator access to your Okta organisation</td></tr><tr><td>Entra ID rights</td><td>Permission to create app registrations, only if Okta is not yet federated to Microsoft 365</td></tr><tr><td>Application address</td><td><code>APP_URL</code> must be set to the address people use to reach Open Archiver. Every address exchanged with Okta derives from it.</td></tr></tbody></table><p>Open <strong>Admin → Single Sign-On</strong> and start a new connection before configuring Okta. The form displays the exact addresses to register; copy them from the page rather than retyping them.</p><table tabindex="0"><thead><tr><th>Address</th><th>Used by</th><th>Example</th></tr></thead><tbody><tr><td><strong>Redirect URI</strong></td><td>OpenID Connect</td><td><code>https://archive.example.com/signin/sso/callback</code></td></tr><tr><td><strong>Service provider metadata URL</strong></td><td>SAML 2.0</td><td><code>https://archive.example.com/api/v1/enterprise/sso/saml/metadata</code></td></tr><tr><td><strong>Assertion consumer service (ACS) URL</strong></td><td>SAML 2.0</td><td><code>https://archive.example.com/signin/sso/callback/saml</code></td></tr></tbody></table><p>Throughout this document, <code>archive.example.com</code> stands for your own Open Archiver address and <code>your-org.okta.com</code> for your own Okta organisation.</p><hr><h2 id="part-1-—-federate-okta-to-microsoft-365" tabindex="-1">Part 1 — Federate Okta to Microsoft 365 <a class="header-anchor" href="#part-1-—-federate-okta-to-microsoft-365" aria-label="Permalink to &quot;Part 1 — Federate Okta to Microsoft 365&quot;">​</a></h2><p>Skip this part if Okta is already federated to Microsoft 365, or if your people authenticate against Okta directly.</p><ol><li><p>In the <a href="https://entra.microsoft.com/" target="_blank" rel="noreferrer">Microsoft Entra admin center</a>, go to <strong>Identity → Applications → App registrations → New registration</strong>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Name</td><td>For example, <code>Okta federation</code></td></tr><tr><td>Supported account types</td><td><strong>Accounts in this organizational directory only</strong></td></tr><tr><td>Redirect URI</td><td>Platform <strong>Web</strong>, value <code>https://your-org.okta.com/oauth2/v1/authorize/callback</code></td></tr></tbody></table><p>The redirect address points at <strong>Okta</strong>, not at Open Archiver. Use your Okta custom domain instead if you have configured one.</p></li><li><p>Note the <strong>Application (client) ID</strong>, then create a secret under <strong>Certificates &amp; secrets → New client secret</strong> and copy its <strong>Value</strong>.</p></li><li><p>In the Okta Admin Console, go to <strong>Security → Identity Providers → Add identity provider → Microsoft</strong> and enter the client ID and secret from the previous steps.</p></li><li><p>Go to <strong>Security → Identity Providers → Routing Rules</strong> and add a rule directing the relevant users to the Microsoft provider. Without a routing rule the Microsoft option never appears on the Okta sign-in page, even though the federation itself is correct.</p></li></ol><p>Confirm this works before continuing: open your Okta sign-in page in a private window and complete a Microsoft sign-in.</p><hr><h2 id="openid-connect" tabindex="-1">OpenID Connect <a class="header-anchor" href="#openid-connect" aria-label="Permalink to &quot;OpenID Connect&quot;">​</a></h2><h3 id="part-2-—-create-the-application-in-okta" tabindex="-1">Part 2 — Create the application in Okta <a class="header-anchor" href="#part-2-—-create-the-application-in-okta" aria-label="Permalink to &quot;Part 2 — Create the application in Okta&quot;">​</a></h3><p>Go to <strong>Applications → Applications → Create App Integration</strong>, select <strong>OIDC - OpenID Connect</strong> and <strong>Web Application</strong>.</p><p><img src="'+e+'" alt="Okta’s &quot;Create a new app integration&quot; dialog with the OIDC - OpenID Connect sign-in method and the Web Application type selected"></p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>App integration name</td><td>For example, <code>Open Archiver</code></td></tr><tr><td>Grant type</td><td><strong>Authorization Code</strong></td></tr><tr><td>Sign-in redirect URI</td><td><code>https://archive.example.com/signin/sso/callback</code></td></tr><tr><td>Sign-out redirect URI</td><td>Leave blank</td></tr></tbody></table><p>Copy the <strong>Client ID</strong> and <strong>Client secret</strong> from the application&#39;s General tab.</p><p><strong>About assignments.</strong> New OpenID Connect applications use Okta&#39;s <em>Federation Broker Mode</em>, which assigns every user in the organisation implicitly. The Assignments tab shows a notice rather than an Assign button, and access is governed by the application&#39;s sign-on policy instead. This is the expected state and needs no action. If your application instead shows a conventional assignment list, assign the people or groups who should have access — the built-in <code>Everyone</code> group is a convenient choice.</p><h3 id="part-3-—-release-group-membership" tabindex="-1">Part 3 — Release group membership <a class="header-anchor" href="#part-3-—-release-group-membership" aria-label="Permalink to &quot;Part 3 — Release group membership&quot;">​</a></h3><p>Okta offers two routes. Route A is recommended: it is purpose-built for groups and requires no expression syntax.</p><div class="warning custom-block"><p class="custom-block-title">Older instructions describe a control that no longer exists</p><p>Many guides direct you to set a &quot;Group claim type&quot; and &quot;Groups claim filter&quot; on the application&#39;s Sign On tab. That control has been withdrawn from current Okta organisations, where the corresponding dialog contains only Issuer and Audience. Use one of the routes below instead.</p></div><h4 id="route-a-—-custom-authorization-server" tabindex="-1">Route A — custom authorization server <a class="header-anchor" href="#route-a-—-custom-authorization-server" aria-label="Permalink to &quot;Route A — custom authorization server&quot;">​</a></h4><p>With this route the issuer becomes <code>https://your-org.okta.com/oauth2/default</code>.</p><p><strong>Step 1 — Add the claim.</strong> Go to <strong>Security → API → Authorization Servers</strong>, select <code>default</code>, then <strong>Claims → Add Claim</strong>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Name</td><td><code>groups</code></td></tr><tr><td>Include in token type</td><td><strong>ID Token</strong>, <strong>Always</strong></td></tr><tr><td>Value type</td><td><strong>Groups</strong></td></tr><tr><td>Filter</td><td><strong>Matches regex</strong>, <code>.*</code></td></tr><tr><td>Include in</td><td><strong>Any scope</strong></td></tr></tbody></table><p><img src="'+o+'" alt="Okta’s Edit Claim dialog showing a claim named groups, included in the ID token always, with value type Groups, a &quot;Matches regex&quot; filter of .*, and included in any scope"></p><p><strong>Include in: Any scope</strong> matters. Open Archiver requests a fixed set of scopes and does not request a <code>groups</code> scope, so a claim restricted to one would never be released.</p><p><strong>Step 2 — Add an access policy <em>and</em> a rule.</strong> On the same authorization server, open <strong>Access Policies</strong>.</p><p>Some Okta organisations provide the <code>default</code> authorization server without an access policy. Where none exists, sign-in fails at Okta before the browser returns to Open Archiver, and no entry appears in the Open Archiver audit log because the request never arrives.</p><p>The two objects do different jobs, and both are required:</p><ul><li>A <strong>policy</strong> is a container. Its only decision is which applications it applies to.</li><li>The <strong>rules</strong> inside it are what actually permit a sign-in. They are evaluated in order, and the first match applies.</li></ul><p><strong>A newly created policy contains no rules and therefore permits nothing.</strong> Select <strong>Add Policy</strong>, assign it to <strong>All clients</strong> or to this application, then <strong>Add Rule</strong> inside it. The template defaults are usually correct; confirm these:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>IF Grant type is</td><td><strong>Authorization Code</strong>, under <em>Client acting on behalf of a user</em></td></tr><tr><td>AND User is</td><td><strong>Any user assigned the app</strong> — under Federation Broker Mode this means everyone</td></tr><tr><td>AND Scopes requested</td><td><strong>Any scopes</strong></td></tr><tr><td>THEN</td><td>Token lifetimes — defaults are appropriate</td></tr></tbody></table><p><img src="'+r+'" alt="Okta’s Edit Rule dialog for an authorization server access policy, with the Authorization Code grant checked, &quot;Any user assigned the app&quot; selected, and &quot;Any scopes&quot; requested"></p><p>When this is correct, the Access Policies tab shows one policy containing one rule, with your application in its assignment list.</p><h4 id="route-b-—-federated-claims" tabindex="-1">Route B — federated claims <a class="header-anchor" href="#route-b-—-federated-claims" aria-label="Permalink to &quot;Route B — federated claims&quot;">​</a></h4><p>With this route the issuer stays <code>https://your-org.okta.com</code>, and no access policy is required.</p><p>On the application&#39;s <strong>Sign On</strong> tab, in the <strong>Token claims</strong> section, select <strong>Add expression</strong>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Name</td><td><code>groups</code></td></tr><tr><td>Value</td><td><code>user.getGroups({&#39;group.profile.name&#39;: &#39;.*&#39;})</code></td></tr><tr><td>Include in</td><td>The <strong>ID token</strong></td></tr></tbody></table><p>The value is an Okta Expression Language expression. Adjust the pattern to narrow which groups are released.</p><h3 id="part-4-—-create-the-groups-to-map" tabindex="-1">Part 4 — Create the groups to map <a class="header-anchor" href="#part-4-—-create-the-groups-to-map" aria-label="Permalink to &quot;Part 4 — Create the groups to map&quot;">​</a></h3><p>Under <strong>Directory → Groups</strong>, create the groups that should correspond to Open Archiver roles — for example <code>archive-admins</code> and <code>archive-auditors</code> — and add the relevant people to them.</p><p>Where Microsoft 365 groups should drive these, Okta can import them through its Microsoft integration; otherwise maintain the groups in Okta directly. Either way, Open Archiver matches on the <strong>Okta</strong> group name.</p><h3 id="part-5-—-create-the-connection-in-open-archiver" tabindex="-1">Part 5 — Create the connection in Open Archiver <a class="header-anchor" href="#part-5-—-create-the-connection-in-open-archiver" aria-label="Permalink to &quot;Part 5 — Create the connection in Open Archiver&quot;">​</a></h3><p><strong>Identity provider</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Protocol</td><td><strong>OpenID Connect</strong></td></tr><tr><td>Display name</td><td><code>Okta</code> — appears on the sign-in page as &quot;Continue with Okta&quot;</td></tr><tr><td>Issuer URL</td><td><code>https://your-org.okta.com/oauth2/default</code> for Route A, or <code>https://your-org.okta.com</code> for Route B</td></tr><tr><td>Client ID</td><td>From Part 2</td></tr><tr><td>Client secret</td><td>From Part 2</td></tr></tbody></table><p><strong>Accounts</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Allowed email domains</td><td>The domain of your <strong>Okta profile</strong> addresses — see the note at the top of this page</td></tr><tr><td>Create accounts on first sign-in</td><td><strong>On</strong>, so people receive an account the first time they sign in</td></tr><tr><td>Link to existing accounts</td><td><strong>On</strong>, so a person who already has an Open Archiver account keeps it</td></tr></tbody></table><p><strong>Roles</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Groups claim</td><td><code>groups</code></td></tr><tr><td>Group mappings</td><td>The Okta group <strong>name</strong> on the left, the Open Archiver role on the right</td></tr><tr><td>Default role</td><td>Recommended, as the fallback for anyone matching no mapping</td></tr><tr><td>Update roles on every sign-in</td><td><strong>On</strong>, so moving a person between Okta groups updates their role</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Okta identifies groups by name</p><p>Enter <code>archive-admins</code>, not a directory object ID — this differs from a direct Entra ID connection, which can identify groups by GUID. Matching is exact and case-sensitive: a group named <code>Everyone</code> is not matched by a mapping written as <code>everyone</code>.</p></div><h3 id="part-6-—-test-then-enable" tabindex="-1">Part 6 — Test, then enable <a class="header-anchor" href="#part-6-—-test-then-enable" aria-label="Permalink to &quot;Part 6 — Test, then enable&quot;">​</a></h3><ol><li>Select <strong>Test connection</strong>. A successful test confirms Open Archiver can reach Okta and read its configuration.</li><li>Turn on <strong>Enable this connection</strong>.</li><li>Save.</li></ol><hr><h2 id="saml-2-0" tabindex="-1">SAML 2.0 <a class="header-anchor" href="#saml-2-0" aria-label="Permalink to &quot;SAML 2.0&quot;">​</a></h2><h3 id="part-2-—-create-the-application-in-okta-1" tabindex="-1">Part 2 — Create the application in Okta <a class="header-anchor" href="#part-2-—-create-the-application-in-okta-1" aria-label="Permalink to &quot;Part 2 — Create the application in Okta&quot;">​</a></h3><p>Go to <strong>Applications → Applications → Create App Integration</strong> and select <strong>SAML 2.0</strong>.</p><p><strong>Configure SAML</strong>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Single sign-on URL</td><td><code>https://archive.example.com/signin/sso/callback/saml</code></td></tr><tr><td>Audience URI (SP Entity ID)</td><td><code>https://archive.example.com/api/v1/enterprise/sso/saml/metadata</code></td></tr><tr><td>Name ID format</td><td><strong>EmailAddress</strong></td></tr><tr><td>Application username</td><td><strong>Email</strong></td></tr></tbody></table><p>Then add a <strong>Group Attribute Statement</strong>:</p><table tabindex="0"><thead><tr><th>Name</th><th>Filter</th></tr></thead><tbody><tr><td><code>groups</code></td><td><strong>Matches regex</strong>, <code>.*</code></td></tr></tbody></table><p>Finish the wizard. From the application&#39;s <strong>Sign On</strong> tab, copy the <strong>Identity Provider metadata</strong> address — it takes the form <code>https://your-org.okta.com/app/&lt;app-id&gt;/sso/saml/metadata</code>.</p><p>Finally, open the <strong>Assignments</strong> tab and assign the people or groups who should have access. SAML applications use conventional assignments, so this step is required even when your OpenID Connect application did not need it.</p><h3 id="part-3-—-create-the-connection-in-open-archiver" tabindex="-1">Part 3 — Create the connection in Open Archiver <a class="header-anchor" href="#part-3-—-create-the-connection-in-open-archiver" aria-label="Permalink to &quot;Part 3 — Create the connection in Open Archiver&quot;">​</a></h3><p><strong>Identity provider</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Protocol</td><td><strong>SAML 2.0</strong></td></tr><tr><td>Display name</td><td><code>Okta</code></td></tr><tr><td>IdP metadata URL</td><td>The Identity Provider metadata address from Part 2</td></tr><tr><td>IdP metadata XML</td><td>Leave empty. Okta&#39;s metadata address is reachable and keeps certificate changes current automatically.</td></tr></tbody></table><p><strong>Accounts</strong> and <strong>Roles</strong> — as for OpenID Connect above, with <strong>Groups claim</strong> set to <code>groups</code>.</p><h3 id="part-4-—-test-then-enable" tabindex="-1">Part 4 — Test, then enable <a class="header-anchor" href="#part-4-—-test-then-enable" aria-label="Permalink to &quot;Part 4 — Test, then enable&quot;">​</a></h3><p>As for OpenID Connect. A successful SAML test reports the sign-in address and the number of signing certificates found in the metadata.</p><hr><h2 id="verify-the-first-sign-in" tabindex="-1">Verify the first sign-in <a class="header-anchor" href="#verify-the-first-sign-in" aria-label="Permalink to &quot;Verify the first sign-in&quot;">​</a></h2><p>Sign in from a private browser window, so existing Okta and Microsoft sessions do not mask the flow.</p><ol><li>Open the Open Archiver sign-in page and select <strong>Continue with Okta</strong>.</li><li>On the Okta sign-in page, choose <strong>Sign in with Microsoft</strong> and authenticate with your work or school account.</li><li>Confirm you arrive at the dashboard.</li></ol><p>Then check the following as an administrator:</p><table tabindex="0"><thead><tr><th>Where</th><th>What to confirm</th></tr></thead><tbody><tr><td><strong>Settings → Users</strong></td><td>The account exists, with the role its Okta group grants rather than the default role</td></tr><tr><td><strong>Compliance → Audit Log</strong></td><td>An account-creation entry for a first sign-in, and a sign-in entry for every one</td></tr><tr><td><strong>Settings → Account</strong> (as that user)</td><td>Password management is hidden for accounts created through single sign-on</td></tr></tbody></table><p>To confirm group mapping is live, move the test user to a different Okta group and sign in again. The role should follow at the next sign-in.</p><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>Two federation steps make diagnosis harder. Check <strong>Okta&#39;s Reports → System Log</strong> first: it shows whether a failure occurred between Okta and Microsoft, or between Open Archiver and Okta. Only then consult the Open Archiver audit log.</p><p>Failed sign-ins show the same brief message to the person signing in. The explanation is recorded in <strong>Compliance → Audit Log</strong>, where each failed sign-in entry names the connection, the address the provider supplied, and the domains the connection permits.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Resolution</th></tr></thead><tbody><tr><td>Sign-in fails; audit log reports a domain that is not allowed</td><td>The address is the <strong>Okta profile</strong> address, whose domain differs from the tenant domain configured</td><td>Add the domain shown in the audit entry — see the note at the top of this page</td></tr><tr><td>Sign-in fails at Okta; nothing appears in the Open Archiver audit log</td><td>The request never reached Open Archiver, usually a missing access policy rule (Route A, Step 2)</td><td>Add a policy and a rule on the <code>default</code> authorization server</td></tr><tr><td>Sign-in succeeds but the role is the default, not the mapped one</td><td>The groups claim is absent or the group names do not match</td><td>Confirm the claim configuration in Part 3, then compare Okta group names against <strong>Group mappings</strong></td></tr><tr><td>The Microsoft option never appears on Okta&#39;s sign-in page</td><td>No routing rule directs users to the Microsoft provider</td><td>Add a routing rule under <strong>Security → Identity Providers → Routing Rules</strong></td></tr><tr><td>Okta reports the user is not assigned</td><td>The person is not assigned to the application (SAML, or an application without Federation Broker Mode)</td><td>Assign them, or the group they belong to, on the application&#39;s Assignments tab</td></tr><tr><td>Federation to Microsoft stops working</td><td>The client secret created in Part 1 has expired</td><td>Create a new secret in Entra ID and update the identity provider configuration in Okta</td></tr><tr><td>No sign-in button appears</td><td>The connection is not enabled, or the license does not include SSO</td><td>Enable the connection; confirm the license under <strong>Admin → License</strong></td></tr></tbody></table><hr><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><ul><li><strong>One connection covers every upstream provider.</strong> Because Okta brokers the sign-in, a single Open Archiver connection serves everyone Okta authenticates, whichever provider sits behind it. Add further providers inside Okta, not as additional Open Archiver connections.</li><li><strong>Group matching is exact and case-sensitive</strong>, and Okta identifies groups by name — not by the directory object IDs a direct Entra ID connection may send.</li><li><strong>The <code>Everyone</code> group is present for every user</strong>, so with a match-everything filter each person always carries at least one group.</li><li><strong>Client secret expiry.</strong> The secret created in Part 1 expires on the schedule you chose in Entra ID. Record the date; federation stops working when it lapses.</li><li><strong>Signing out.</strong> Signing out of Open Archiver ends neither the Okta nor the Microsoft session. Use a private window when testing repeatedly.</li></ul><p>For the roles model, running several providers at once, and requiring single sign-on, see the <a href="./../guide.html">SSO guide</a>.</p>',90)]))}const y=n(d,[["render",c]]);export{f as __pageData,y as default};
